//==============================================================================
// encoder_qdec.v -- 增量式正交编码器 4 倍频计数 (A/B 两相)
//----------------------------------------------------------------------------
// A/B 两相先过 3 级同步器去亚稳态, 再用"上一状态 -> 当前状态"的跳变表计数:
//   正转序列 00->01->11->10->00 ... 每个沿 +1
//   反转序列 00->10->11->01->00 ... 每个沿 -1
// pos 为有符号位置计数(32 位, 正转增加), dir 记录最近一次方向。
// 4 倍频: A、B 的每个边沿都计数, 分辨率 = 4 x 编码器线数 x 减速比。
//==============================================================================
`timescale 1ns / 1ps

module encoder_qdec #(
    parameter CNT_W = 32
)(
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire                    a,          // 编码器 A 相
    input  wire                    b,          // 编码器 B 相
    output reg  signed [CNT_W-1:0] pos,        // 位置计数(4 倍频)
    output reg                     dir         // 1 = 正转, 0 = 反转
);

    //------------------------------------------------------------------
    // 3 级同步 + 取沿
    //------------------------------------------------------------------
    reg [2:0] a_s, b_s;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_s <= 3'b111;
            b_s <= 3'b111;
        end else begin
            a_s <= {a_s[1:0], a};
            b_s <= {b_s[1:0], b};
        end
    end

    wire aq = a_s[2];
    wire bq = b_s[2];

    reg aq_d, bq_d;

    //------------------------------------------------------------------
    // 跳变表: {上一A, 上一B, 当前A, 当前B}
    //------------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            aq_d <= 1'b0;
            bq_d <= 1'b0;
            pos  <= {CNT_W{1'b0}};
            dir  <= 1'b0;
        end else begin
            aq_d <= aq;
            bq_d <= bq;
            case ({aq_d, bq_d, aq, bq})
            // ---- 正转: 每个有效沿 +1 ----
            4'b00_01, 4'b01_11, 4'b11_10, 4'b10_00: begin
                pos <= pos + 1'b1;
                dir <= 1'b1;
            end
            // ---- 反转: 每个有效沿 -1 ----
            4'b00_10, 4'b10_11, 4'b11_01, 4'b01_00: begin
                pos <= pos - 1'b1;
                dir <= 1'b0;
            end
            // 其它(无变化 / 两相同时跳变)不计数
            default: ;
            endcase
        end
    end

endmodule
